        assert_eq!(median(&[1, 2, 3]), Some(2.0));
        assert_eq!(median(&[5]), Some(5.0));
    }

    #[test]
    fn even() {
        assert_eq!(median(&[3, 1, 2, 4]), Some(2.5));
        assert_eq!(median(&[1, 2, 3, 4]), Some(2.5));
    }

    #[test]
    fn max_values() {
        let max = i64::MAX;
        assert_eq!(median(&[max, max, max]), Some(max as f64));
        assert_eq!(
            median(&[max, max, max, max]),
            Some(max as f64 + 0.5)
        );
    }

